41	import { mathMax } from '../../util/number';
42	
43	
44	export interface MatrixCellLayoutInfo {
45	    type: MatrixCellLayoutInfoType;
46	    // Represents col/row, serves as both id and locator.
47	    // For a `MatrixDimensionCell`:
48	    //  it is `setDimXYValue(new Point(), dimIdx, firstLeafLocator, level - _levels.length)`.
49	    //  e.g., `id[dimIdx]` is `0` or `1` or `2` or `3` if there are at most `4` leaves in the tree.
50	    // For a `MatrixDimensionLevelInfo`:
51	    //  it is `setDimXYValue(new Point(), dimIdx, 0, level - _levels.length)`
52	    //  e.g., `id[1 - dimIdx]` is `-3` or `-2` or `-1` if the tree has `3` levels.
53	    // If negative, locate to corner cells; otherwise, locate to body cells.
54	    id: Point;
55	    // By pixel. Computed left-top x (for x dimension) or y (for y dimension).
56	    // Used to locate.
57	    xy: number;
58	    // By pixel. Computed height (for x dimension) or width (for y dimension).
59	    // Used to locate.
60	    wh: number;
61	    dim: MatrixDim;
62	}
63	
64	
65	export type MatrixXYLocator = MatrixCellLayoutInfo['id']['x'] | MatrixCellLayoutInfo['id']['y'];
66	/**
67	 * [[xmin, xmax], [ymin, ymax]]
68	 * For each internal value, be NaN if invalid or out of boundary (never be null/undefined),
69	 * otherwise must be valid locators.
70	 * @see parseCoordRangeOption
71	 * @see resetXYLocatorRange
72	 */
73	export type MatrixXYLocatorRange = MatrixXYLocator[][] & {__brand: 'MatrixXYLocatorRange'};
74	/**
75	 * [[xmin, xmax], [ymin, ymax]], be `NullUndefined` if illegal.
76	 */
77	export type MatrixXYCellLayoutInfoRange = (MatrixCellLayoutInfo | NullUndefined)[][];
78	
79	export interface MatrixDimensionCell extends MatrixCellLayoutInfo {
80	    // Computed col/row span. Always exists and >= 1.
81	    // `span[XY[dimIdx]]` is actually the leaves count of this subtree.
82	    span: Point;
83	    // Start from 0, tree depth.
84	    level: number;
85	    // It is both `MatrixXYLocator` and `OrdinalNumber` and _cell[index].
86	    firstLeafLocator: MatrixXYLocator;
87	    // Used to fatch its raw value by `matrixDim.getOrdinalMeta().category[ordinal]`,
88	    // or feach cell by `_cells[ordinal]`.
89	    // The ordinal of the leaf nodes is the same as `id.getOnDim(0)` for quick query,
90	    // but not the same for non-leaf nodes.
91	    ordinal: OrdinalNumber;
92	    // Normalized raw option of `matrix.x/y.data[i]`, not include any parents option.
93	    // Never be NullUndefined
94	    option: MatrixDimensionCellOption;
95	    // The layout rect for rendering. Available after matrix coordinate system resizing.
96	    rect: RectLike;
97	}
98	
99	/**
100	 * Computed properties of a certain tree level.
101	 * In most cases this is used to describe level size or locate corner cells.
102	 */
103	export interface MatrixDimensionLevelInfo extends MatrixCellLayoutInfo {
104	    // The raw option of `matrix.levels[i]`
105	    option: MatrixDimensionLevelOption | NullUndefined;
106	}
107	
108	export type MatrixDimPair = {
109	    x: MatrixDim;
110	    y: MatrixDim;
111	};
112	
113	/**
114	 * Lifetime: the same with `MatrixModel`, but different from `coord/Matrix`.
115	 */
116	export class MatrixDim {
117	    // Use it to visit `cell.id` and `cell.span`
118	    readonly dim: 'x' | 'y';
119	    // Must be `0 | 1`, corresponding to 'x' | 'y'
120	    readonly dimIdx: number;
121	
122	    // Under the current definition, every leave corresponds a unit cell,
123	    // and leaves can serve as the locator of cells.
124	    // Therefore make sure:
125	    //  - The first `_leavesCount` elements in `_cells` are leaves.
126	    //  - `_cells[leaf.id[XY[this.dimIdx]]]` is the leaf itself.
127	    //  - Leaves of each subtree are placed together, that is, the leaves of a dimCell are:
128	    //    `this._cells.slice(dimCell.firstLeafLocator, dimCell.span[XY[this.dimIdx]])`
129	    private _cells: MatrixDimensionCell[] = [];
130	
131	    // Can be visited by `_levels[cell.level]` or `_levels[cell.id[1 - dimIdx] + _levels.length]`.
132	    // Items are never be null/undefined after initialized.
133	    private _levels: MatrixDimensionLevelInfo[] = [];
134	
135	    private _leavesCount: number;
136	
137	    private _model: MatrixDimensionModel;
138	    private _ordinalMeta: OrdinalMeta;
139	    // Only for uniformly parsing.
140	    private _scale: Ordinal;
141	
142	    private _uniqueValueGen: ReturnType<typeof createUniqueValueGenerator>;
143	
144	    constructor(dim: 'x' | 'y', dimModel: MatrixDimensionModel) {
145	        this.dim = dim;
146	        this.dimIdx = dim === 'x' ? 0 : 1;
147	        this._model = dimModel;
148	
149	        this._uniqueValueGen = createUniqueValueGenerator(dim);
150	
151	        let dimModelData = dimModel.get('data', true);
152	        if (dimModelData != null && !isArray(dimModelData)) {
153	            if (__DEV__) {
154	                error(`Illegal echarts option - matrix.${this.dim}.data must be an array if specified.`);
155	            }
156	            dimModelData = [];
157	        }
158	        if (dimModelData) {
159	            this._initByDimModelData(dimModelData);
160	        }
161	        else {
162	            this._initBySeriesData();
163	        }
164	    }
165	
166	    private _initByDimModelData(dimModelData: MatrixDimensionCellLooseOption[]) {
167	        const self = this;
168	        const _cells = self._cells;
169	        const _levels = self._levels;
170	        const sameLocatorCellsLists: MatrixDimensionCell[][] = []; // Save for sorting.
171	        let _cellCount = 0;
172	
173	        self._leavesCount = traverseInitCells(dimModelData, 0, 0);
174	
175	        postInitCells();
176	
177	        return;
178	
179	        function traverseInitCells(
180	            dimModelData: MatrixDimensionCellLooseOption[] | NullUndefined,
181	            firstLeafLocator: number,
182	            level: number
183	        ): number {
184	            let totalSpan = 0;
185	            if (!dimModelData) {
186	                return totalSpan;
187	            }
188	
189	            each(dimModelData, (option, optionIdx) => {
190	                let invalidOption = false;
191	                let cellOption: MatrixDimensionCell['option'];
192	                if (isString(option)) {
193	                    cellOption = {value: option};
194	                }
195	                else if (isObject(option)) {
196	                    cellOption = option;
197	                    if (option.value != null && !isString(option.value)) {
198	                        invalidOption = true;
199	                        cellOption = {value: null};
200	                    }
201	                }
202	                else {
203	                    cellOption = {value: null};
204	                    if (option != null) {
205	                        invalidOption = true;
206	                    }
207	                }
208	
209	                if (invalidOption) {
210	                    if (__DEV__) {
211	                        error(`Illegal echarts option - matrix.${self.dim}.data[${optionIdx}]`
212	                            + ' must be `string | {value: string}`.'
213	                        );
214	                    }
215	                }
216	
217	                const cell: MatrixDimensionCell = {
218	                    type: MatrixCellLayoutInfoType.nonLeaf, // Update to leaf later if it's a leaf.
219	                    ordinal: NaN, // Set it later.
220	                    level,
221	                    firstLeafLocator,
222	                    id: new Point(), // Set it in `_initCellsId`.
223	                    span: setDimXYValue(new Point(), self.dimIdx, 1, 1),
224	                    option: cellOption,
225	                    xy: NaN,
226	                    wh: NaN,
227	                    dim: self,
228	                    rect: createNaNRectLike(),
229	                };
230	                _cellCount++;
231	                (sameLocatorCellsLists[firstLeafLocator]
232	                    || (sameLocatorCellsLists[firstLeafLocator] = [])
233	                ).push(cell);
234	
235	                if (!_levels[level]) {
