35	export const MatrixCellLayoutInfoType = {
36	    level: 1,
37	    leaf: 2,
38	    nonLeaf: 3,
39	} as const;
40	export type MatrixCellLayoutInfoType = (typeof MatrixCellLayoutInfoType)[keyof typeof MatrixCellLayoutInfoType];
