88	/**
89	 * If illegal or out of boundary, set NaN to `locOut`. (See `isLocatorRangeInvalidOnDim`)
90	 * x dimension and y dimension are calculated separately.
91	 */
92	export function parseCoordRangeOption(
93	    locOut: MatrixXYLocatorRange,
94	    // If illegal input or can not find any target, save reason to it.
95	    // Do nothing if `NullUndefined`.
96	    reasonOut: string[] | NullUndefined,
97	    data: MatrixCoordRangeOption[],
98	    dims: MatrixDimPair,
99	    clamp: MatrixClampOption,
100	): void {
101	    // x and y are supported to be handled separately - if one dimension is invalid
102	    // (may be users do not need that), the other one should also be calculated.
103	    parseCoordRangeOptionOnOneDim(locOut[0], reasonOut, clamp, data, dims, 0);
104	    parseCoordRangeOptionOnOneDim(locOut[1], reasonOut, clamp, data, dims, 1);
105	}
106	
107	function parseCoordRangeOptionOnOneDim(
108	    locDimOut: MatrixXYLocatorRange[number],
109	    reasonOut: string[] | NullUndefined,
110	    clamp: MatrixClampOption,
111	    data: MatrixCoordRangeOption[],
112	    dims: MatrixDimPair,
113	    dimIdx: number,
114	): void {
115	    locDimOut[0] = Infinity;
116	    locDimOut[1] = -Infinity;
117	
118	    const dataOnDim = data[dimIdx];
119	    const coordValArr = isArray(dataOnDim) ? dataOnDim : [dataOnDim];
120	    const len = coordValArr.length;
121	    const hasClamp = !!clamp;
122	
123	    if (len === 1 || len === 2) {
124	        parseCoordRangeOptionOnOneDimOnePart(locDimOut, reasonOut, coordValArr, hasClamp, dims, dimIdx, 0);
125	        if (len > 1) {
126	            parseCoordRangeOptionOnOneDimOnePart(locDimOut, reasonOut, coordValArr, hasClamp, dims, dimIdx, 1);
127	        }
128	    }
129	    else {
130	        if (reasonOut) {
131	            reasonOut.push(`Can only contain 1 or 2 coords, rather than ${len}.`);
132	        }
133	        locDimOut[0] = locDimOut[1] = NaN;
134	    }
135	
136	    if (hasClamp) {
137	        // null/undefined/NaN or illegal data represents the entire row/column;
138	        // Cover the entire locator regardless of body or corner, and confine it later.
139	        let locLowerBound = -dims[XY[1 - dimIdx]].getLocatorCount(dimIdx);
140	        let locUpperBound = dims[XY[dimIdx]].getLocatorCount(dimIdx) - 1;
141	
142	        if (clamp === MatrixClampOption.body) {
143	            locLowerBound = mathMax(0, locLowerBound);
144	        }
145	        else if (clamp === MatrixClampOption.corner) {
146	            locUpperBound = mathMin(-1, locUpperBound);
147	        }
148	
149	        if (locUpperBound < locLowerBound) { // Also considered that both x and y has no cell.
150	            locLowerBound = locUpperBound = NaN;
151	        }
152	
153	        if (eqNaN(locDimOut[0])) {
154	            locDimOut[0] = locLowerBound;
155	        }
156	        if (eqNaN(locDimOut[1])) {
157	            locDimOut[1] = locUpperBound;
158	        }
159	        locDimOut[0] = mathMax(mathMin(locDimOut[0], locUpperBound), locLowerBound);
160	        locDimOut[1] = mathMax(mathMin(locDimOut[1], locUpperBound), locLowerBound);
161	    }
162	}
163	
164	// The return val must be finite or NaN.
165	function parseCoordRangeOptionOnOneDimOnePart(
166	    locDimOut: MatrixXYLocatorRange[number],
167	    reasonOut: string[] | NullUndefined,
168	    coordValArr: MatrixCoordValueOption[],
169	    hasClamp: boolean,
170	    dims: MatrixDimPair,
171	    dimIdx: number,
172	    partIdx: number,
173	): void {
174	    const layout = coordDataToAllCellLevelLayout(coordValArr[partIdx], dims, dimIdx);
175	    if (!layout) {
176	        if (!hasClamp && reasonOut) {
177	            reasonOut.push(`Can not find layout by coord[${dimIdx}][${partIdx}].`);
178	        }
179	        locDimOut[0] = locDimOut[1] = NaN;
180	        return;
181	    }
182	    const locatorA = layout.id[XY[dimIdx]];
183	    let locatorB = locatorA;
184	    const dimCell = cellLayoutInfoToDimCell(layout);
185	    if (dimCell) { // Handle non-leaf
186	        locatorB += dimCell.span[XY[dimIdx]] - 1;
187	    }
188	    locDimOut[0] = mathMin(locDimOut[0], locatorA, locatorB);
189	    locDimOut[1] = mathMax(locDimOut[1], locatorA, locatorB);
190	}
