240	// Return whether intersect.
241	// `thisLocRange` will be expanded (modified) if an intersection is encountered.
242	function expandXYLocatorRangeIfIntersect(
243	    thisLocRange: MatrixXYLocatorRange,
244	    otherLocRange: MatrixXYLocatorRange
245	): boolean {
246	    if (!locatorRangeIntersectOneDim(thisLocRange[0], otherLocRange[0])
247	        || !locatorRangeIntersectOneDim(thisLocRange[1], otherLocRange[1])
248	    ) {
249	        return false;
250	    }
251	
252	    thisLocRange[0][0] = mathMin(thisLocRange[0][0], otherLocRange[0][0]);
253	    thisLocRange[0][1] = mathMax(thisLocRange[0][1], otherLocRange[0][1]);
254	    thisLocRange[1][0] = mathMin(thisLocRange[1][0], otherLocRange[1][0]);
255	    thisLocRange[1][1] = mathMax(thisLocRange[1][1], otherLocRange[1][1]);
256	
257	    return true;
258	}
259	
260	// Notice: If containing NaN, not intersect.
261	function locatorRangeIntersectOneDim(
262	    locRange1OneDim: MatrixXYLocatorRange[number],
263	    locRange2OneDim: MatrixXYLocatorRange[number],
264	): boolean {
265	    return (
266	        locRange1OneDim[1] >= locRange2OneDim[0]
267	        && locRange1OneDim[0] <= locRange2OneDim[1]
268	    );
269	}
