271	export function fillIdSpanFromLocatorRange(
272	    owner: {id: Point; span: Point;},
273	    locatorRange: MatrixXYLocatorRange
274	): void {
275	    owner.id.set(locatorRange[0][0], locatorRange[1][0]);
276	    owner.span.set(locatorRange[0][1] - owner.id.x + 1, locatorRange[1][1] - owner.id.y + 1);
277	}
