279	export function cloneXYLocatorRange(
280	    target: MatrixXYLocatorRange,
281	    source: MatrixXYLocatorRange
282	): void {
283	    target[0][0] = source[0][0];
284	    target[0][1] = source[0][1];
285	    target[1][0] = source[1][0];
286	    target[1][1] = source[1][1];
