289	/**
290	 * If illegal, the corresponding x/y/width/height is set to `NaN`.
291	 * `x/width` or `y/height` is supported to be calculated separately,
292	 * i.e., one side are NaN, the other side are normal.
293	 * @param oneDimOut only write to `x/width` or `y/height`, depending on `dimIdx`.
294	 */
295	export function xyLocatorRangeToRectOneDim(
296	    oneDimOut: RectLike,
297	    locRange: MatrixXYLocatorRange,
298	    dims: MatrixDimPair,
299	    dimIdx: number
300	) {
301	    const layoutMin = coordDataToAllCellLevelLayout(locRange[dimIdx][0], dims, dimIdx);
302	    const layoutMax = coordDataToAllCellLevelLayout(locRange[dimIdx][1], dims, dimIdx);
303	
304	    oneDimOut[XY[dimIdx]] = oneDimOut[WH[dimIdx]] = NaN;
305	
306	    if (layoutMin && layoutMax) {
307	        oneDimOut[XY[dimIdx]] = layoutMin.xy;
308	        oneDimOut[WH[dimIdx]] = layoutMax.xy + layoutMax.wh - layoutMin.xy;
309	    }
310	}
