336	/**
337	 * @usage To get/set on dimension, use:
338	 *  `xyVal[XY[dim]] = val;` // set on this dimension.
339	 *  `xyVal[XY[1 - dim]] = val;` // set on the perpendicular dimension.
340	 */
341	export function setDimXYValue(
342	    out: Point,
343	    dimIdx: number, // 0 | 1
344	    valueOnThisDim: MatrixXYLocator,
345	    valueOnOtherDim: MatrixXYLocator
346	): Point {
347	    out[XY[dimIdx]] = valueOnThisDim;
348	    out[XY[1 - dimIdx]] = valueOnOtherDim;
349	    return out;
