352	/**
353	 * Return NullUndefined if not dimension cell.
354	 */
355	function cellLayoutInfoToDimCell(
356	    cellLayoutInfo: MatrixCellLayoutInfo | NullUndefined
357	): MatrixDimensionCell | NullUndefined {
358	    return (
359	        cellLayoutInfo && (
360	            cellLayoutInfo.type === MatrixCellLayoutInfoType.leaf
361	            || cellLayoutInfo.type === MatrixCellLayoutInfoType.nonLeaf
362	        )
363	    ) ? (cellLayoutInfo as MatrixDimensionCell) : null;
364	}
